package br.gov.demo.sjpgeo;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.*;import android.webkit.*;import android.widget.*;import androidx.webkit.WebViewAssetLoader;import androidx.webkit.WebViewAssetLoader.AssetsPathHandler;import androidx.webkit.WebViewAssetLoader.ResourcesPathHandler;

public class MainActivity extends Activity {
 WebView web; ValueCallback<Uri[]> chooser; static final int FILE=110, LOC=111; String pendingTech="";
 @Override public void onCreate(Bundle b){super.onCreate(b);web=new WebView(this);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(true);web.addJavascriptInterface(new Bridge(),"SjpAndroid");
 WebViewAssetLoader loader=new WebViewAssetLoader.Builder().addPathHandler("/assets/",new AssetsPathHandler(this)).build();
 web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){return loader.shouldInterceptRequest(request.getUrl());}});
 web.setWebChromeClient(new WebChromeClient(){@Override public void onGeolocationPermissionsShowPrompt(String origin,GeolocationPermissions.Callback cb){boolean granted=checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;cb.invoke(origin,granted,false);if(!granted)requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},LOC);}
 @Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> cb,FileChooserParams params){if(chooser!=null)chooser.onReceiveValue(null);chooser=cb;try{startActivityForResult(params.createIntent(),FILE);return true;}catch(Exception e){chooser=null;return false;}}});
 web.loadUrl("https://appassets.androidplatform.net/assets/index.html");}
 class Bridge { @JavascriptInterface public void startShift(String tech){runOnUiThread(()->{if(!tech.equals("tecnico1")&&!tech.equals("tecnico2"))return;pendingTech=tech;startTracking();});} @JavascriptInterface public void endShift(){runOnUiThread(()->{pendingTech="";stopService(new Intent(MainActivity.this,LocationService.class));});}}
 void startTracking(){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED && checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},LOC);return;}Intent i=new Intent(this,LocationService.class);i.putExtra("technician",pendingTech);try{startForegroundService(i);}catch(Exception e){Toast.makeText(this,"Não foi possível iniciar GPS: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==LOC&&g.length>0&&(g[0]==PackageManager.PERMISSION_GRANTED||(g.length>1&&g[1]==PackageManager.PERMISSION_GRANTED)))startTracking();}
 @Override protected void onActivityResult(int r,int c,Intent data){super.onActivityResult(r,c,data);if(r==FILE&&chooser!=null){chooser.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(c,data));chooser=null;}}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
}
